{
  "info": {
    "title": "UAE Account Information API",
    "description": "## UAE Open Finance Account Information API Specification",
    "version": "v2.2-rc2"
  },
  "servers": [
    {
      "url": "/open-finance/account-information/v2.2"
    }
  ],
  "source_path": "/accounts/{AccountId}/beneficiaries",
  "operations": {
    "get": {
      "tags": [
        "Beneficiaries"
      ],
      "summary": "Get Beneficiaries",
      "description": "The following permissions are applicable to this resource:\n\n* ReadBeneficiariesBasic\n\n* ReadBeneficiariesDetail\n\nRefer to the Permissions and Data Clusters section of the Customer Data page for further information.\n",
      "operationId": "GetAccountsAccountIdBeneficiaries",
      "parameters": [
        {
          "$ref": "#/components/parameters/Authorization"
        },
        {
          "$ref": "#/components/parameters/AccountId"
        },
        {
          "$ref": "#/components/parameters/x-fapi-auth-date"
        },
        {
          "$ref": "#/components/parameters/x-fapi-customer-ip-address"
        },
        {
          "$ref": "#/components/parameters/x-fapi-interaction-id"
        },
        {
          "$ref": "#/components/parameters/x-customer-user-agent"
        }
      ],
      "responses": {
        "200": {
          "$ref": "#/components/responses/200AccountsAccountIdBeneficiariesRead"
        },
        "400": {
          "$ref": "#/components/responses/400Error"
        },
        "401": {
          "$ref": "#/components/responses/401Error"
        },
        "403": {
          "$ref": "#/components/responses/403Error"
        },
        "405": {
          "$ref": "#/components/responses/405Error"
        },
        "406": {
          "$ref": "#/components/responses/406Error"
        },
        "429": {
          "$ref": "#/components/responses/429Error"
        },
        "500": {
          "$ref": "#/components/responses/500Error"
        }
      },
      "security": [
        {
          "UserOAuth2Security": [
            "openid",
            "accounts"
          ]
        }
      ]
    }
  }
}

{
  "name": "authorization",
  "in": "header",
  "required": true,
  "description": "An authorization Token as per https://tools.ietf.org/html/rfc6750",
  "schema": {
    "type": "string"
  }
}

{
  "name": "AccountId",
  "in": "path",
  "description": "AccountId",
  "required": true,
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-fapi-auth-date",
  "required": false,
  "description": "The time when the User last logged in with the TPP. \nAll dates in the HTTP headers are represented as RFC 7231 Full Dates. An example is below: \nSun, 10 Sep 2017 19:43:31 UTC",
  "schema": {
    "type": "string",
    "pattern": "^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), \\d{2} (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \\d{4} \\d{2}:\\d{2}:\\d{2} (GMT|UTC)$"
  }
}

{
  "in": "header",
  "name": "x-fapi-customer-ip-address",
  "required": false,
  "description": "The User's IP address if the User is currently logged in with the TPP.",
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-fapi-interaction-id",
  "required": false,
  "description": "An RFC4122 UID used as a correlation id.",
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-customer-user-agent",
  "description": "Indicates the user-agent that the User is using.",
  "required": false,
  "schema": {
    "type": "string"
  }
}

{
  "description": "Beneficiaries Read",
  "headers": {
    "x-fapi-interaction-id": {
      "description": "An RFC4122 UID used as a correlation id.",
      "required": true,
      "schema": {
        "type": "string"
      }
    }
  },
  "content": {
    "application/json; charset=utf-8": {
      "schema": {
        "$ref": "#/components/schemas/AEReadBeneficiary"
      }
    },
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/AEReadBeneficiary"
      }
    },
    "application/jwt": {
      "schema": {
        "$ref": "#/components/schemas/AEReadBeneficiarySigned"
      }
    }
  }
}

{
  "description": "List of Beneficiaries for an Account",
  "type": "object",
  "required": [
    "Data",
    "Links",
    "Meta"
  ],
  "properties": {
    "Data": {
      "type": "object",
      "description": "Primary data for the resource",
      "required": [
        "AccountId",
        "Beneficiary"
      ],
      "properties": {
        "AccountId": {
          "$ref": "#/components/schemas/AccountId"
        },
        "Beneficiary": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/AEBeneficiary"
          }
        }
      },
      "additionalProperties": false
    },
    "Links": {
      "$ref": "#/components/schemas/Links"
    },
    "Meta": {
      "$ref": "#/components/schemas/MetaTotalPages"
    }
  },
  "additionalProperties": false
}

{
  "description": "A unique and immutable identifier produced by the LFI to identify the account resource.This identifier has no meaning to the account owner (User 1).",
  "type": "string",
  "minLength": 1,
  "maxLength": 40
}

{
  "description": "Beneficiaries for a specific AccountId",
  "type": "object",
  "required": [
    "BeneficiaryId",
    "BeneficiaryType",
    "AddedViaOF"
  ],
  "properties": {
    "BeneficiaryId": {
      "$ref": "#/components/schemas/BeneficiaryId"
    },
    "BeneficiaryType": {
      "$ref": "#/components/schemas/AEBeneficiaryTypeCode"
    },
    "AddedViaOF": {
      "description": "Indicates whether the Beneficiary record was created as part of an Open Finance (OF) payment. If false, the Beneficiary was created through an existing LFI channel.",
      "type": "boolean"
    },
    "AccountHolderName": {
      "$ref": "#/components/schemas/AccountHolderName"
    },
    "AccountHolderShortName": {
      "$ref": "#/components/schemas/AccountHolderShortName"
    },
    "Reference": {
      "$ref": "#/components/schemas/Reference"
    },
    "SupplementaryData": {
      "$ref": "#/components/schemas/AESupplementaryData"
    },
    "CreditorAgent": {
      "$ref": "#/components/schemas/AEBranchAndFinancialInstitutionIdentification6_0"
    },
    "CreditorAccount": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/AECashAccount5_0"
      }
    }
  },
  "additionalProperties": false
}

{
  "description": "A unique and immutable identifier used to identify the beneficiary resource. This identifier has no meaning to the account owner.",
  "type": "string",
  "minLength": 1,
  "maxLength": 40
}

{
  "description": "Specifies the Beneficiary Type. Encoded with allowable values of: 'Activated' - Beneficiary has been added to the beneficiary list using SCA. 'NotActivated' - Beneficiary has been added to the beneficiary list without SCA",
  "type": "string",
  "enum": [
    "Activated",
    "NotActivated"
  ]
}

{
  "description": "Unique reference in the context of the creditor, provided by the creditor to the User1 (Debtor), to unambiguously refer to the payment transaction. Usage: If available, the initiating party (i.e. Debtor) provides this reference in the structured remittance information, to enable reconciliation by the Creditor upon receipt of the amount of money. This field is populated by the User 1 (who is the initiating party of the payment e.g. the Debtor). Field is free format text",
  "type": "string",
  "minLength": 1,
  "maxLength": 35
}

{
  "type": "object",
  "description": "Additional information that can not be captured in the structured fields and/or any other specific block."
}

{
  "type": "object",
  "description": "Party that manages the account on behalf of the account owner, that is manages the registration and booking of entries on the account, calculates balances on the account and provides information about the account.\nThis is the servicer of the beneficiary account.",
  "required": [
    "SchemeName",
    "Identification"
  ],
  "properties": {
    "SchemeName": {
      "$ref": "#/components/schemas/AEExternalFinancialInstitutionIdentificationCode"
    },
    "Identification": {
      "$ref": "#/components/schemas/Identification_1"
    },
    "Name": {
      "$ref": "#/components/schemas/Name_1"
    },
    "PostalAddress": {
      "$ref": "#/components/schemas/AEPostalAddress"
    }
  },
  "additionalProperties": false
}

{
  "description": "Address properties based on ISO 20022 `PostalAddress27` definition",
  "type": "object",
  "required": [
    "AddressLine",
    "Country"
  ],
  "properties": {
    "AddressType": {
      "description": "The type of address. Omitted if type not held.",
      "type": "string",
      "enum": [
        "Billing",
        "Business",
        "Correspondence",
        "DeliveryTo",
        "MailTo",
        "POBox",
        "Postal",
        "Permanent",
        "Residential",
        "Statement",
        "Other"
      ]
    },
    "AddressLine": {
      "description": "Information that locates and identifies a specific address for a transaction entry, that is presented in free format text.",
      "type": "array",
      "minItems": 1,
      "maxItems": 7,
      "items": {
        "type": "string",
        "minLength": 1,
        "maxLength": 70
      }
    },
    "BuildingNumber": {
      "description": "The unit, apartment, or villa number within a building or community",
      "type": "string",
      "minLength": 1,
      "maxLength": 16
    },
    "BuildingName": {
      "description": "Name of the building or house.",
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "Floor": {
      "description": "Floor or storey within a building.",
      "type": "string",
      "minLength": 1,
      "maxLength": 70
    },
    "StreetName": {
      "description": "The name of the street or road where the property is located.",
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "DistrictName": {
      "description": "The district, community, or neighbourhood where the property is located.",
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "PostBox": {
      "description": "The P.O. Box number assigned to the recipient for mail delivery.",
      "type": "string",
      "minLength": 1,
      "maxLength": 16
    },
    "TownName": {
      "description": "Name of a built-up area, such as a town or city.",
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "CountrySubDivision": {
      "description": "Country subdivision, such as state or province. This is the Emirate where the address is registered.",
      "type": "string",
      "enum": [
        "AbuDhabi",
        "Ajman",
        "Dubai",
        "Fujairah",
        "RasAlKhaimah",
        "Sharjah",
        "UmmAlQuwain"
      ]
    },
    "Country": {
      "description": "The country associated with the address, represented using the ISO 3166-1 alpha-2 country code.",
      "type": "string",
      "pattern": "^[A-Z]{2}$"
    }
  },
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "SchemeName",
    "Identification"
  ],
  "description": "Provides the details to identify the beneficiary account.",
  "properties": {
    "SchemeName": {
      "$ref": "#/components/schemas/AEExternalAccountIdentificationCode1"
    },
    "Identification": {
      "$ref": "#/components/schemas/Identification_0"
    }
  },
  "additionalProperties": false
}

{
  "description": "Identification for the account assigned by the LFI based on the Account Scheme Name. This identification is known by the User 1 account owner. For IBAN, refer to the ISO Standard 13616.\n",
  "type": "string",
  "minLength": 1,
  "maxLength": 400
}

